/**
 * Records one node and reports whether the walk should continue below it.
 *
 * @param Node $node  The node the traversal reached
 * @param int  $depth How far below the root symbol it sits
 *
 * @return bool True when the traversal should descend into this node
 */
public function visit(Node $node, int $depth): bool
{
    $continuation = $this->expansion->reach($node, $depth);
    if (!$continuation->reported()) {
        return false;
    }

    $parent = $depth > 0 ? ($this->parents[$depth - 1] ?? null) : null;
    $meta = $node->meta();

    $this->reached[] = [
        'id' => $node->id()->toString(),
        'kind' => $node->kind()->value,
        'resolved' => $node->resolved(),
        'depth' => $depth,
        'parent' => $parent?->toString(),
        'relations' => $parent === null ? [] : $this->relations($parent, $node->id()),
        'truncated' => $continuation->marker(),
        'file' => $meta === null ? null : ['path' => $meta->path, 'line' => $meta->line, 'column' => $meta->column],
    ];

    $this->parents[$depth] = $node->id();

    return $continuation->descends();
}

     * @param Graph           $graph  The dependency graph to report on
     * @param NodeId<Node>    $symbol The symbol the walk starts at
     * @param OutputInterface $output Where the digraph is written
     */
    public function report(Graph $graph, NodeId $symbol, OutputInterface $output): void
    {
        $cursor = new DotCursor($graph, $this->traversal, $this->level);
        $this->traversal->traverse($graph, $symbol, $cursor->visit(...));

        $nodes = $cursor->nodes();
        if ($nodes === []) {
            return;
        }

        $statements = $this->renderer->open($symbol->toString());
        foreach ($nodes as $node) {
            $statements[] = $this->renderer->node($node);
        }
        foreach ($cursor->edges() as $edge) {
            $statements[] = $this->renderer->edge($edge);
        }
        $statements[] = $this->renderer->close();

        $output->writeln($statements, OutputInterface::OUTPUT_RAW);
    }
}

